const htmlEscape = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const boolish = (value) => value === true || String(value).toLowerCase() === 'true' || String(value) === '1';
const subjectText = (value) => String(value ?? '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 180);
return $input.all().flatMap((item, index) => {
  const row = item.json || {};
  if (!row.id || String(row.status || '') !== 'Needs Review' || boolish(row.review_alert_sent)) return [];
  const filename = subjectText(row.filename || 'unnamed-document');
  const reason = String(row.review_reason || row.validation_errors || 'human_review_required');
  const messageHtml = [
    '<p><strong>Document review alert retry</strong></p>',
    '<p>Filename: ' + htmlEscape(filename) + '</p>',
    '<p>Type: ' + htmlEscape(row.document_type || 'Unknown') + '</p>',
    '<p>Party: ' + htmlEscape(row.party_name || '') + '</p>',
    '<p>Confidence: ' + htmlEscape(row.confidence ?? '') + '</p>',
    '<p>Reason: ' + htmlEscape(reason) + '</p>',
    '<p>Safe review path: ' + htmlEscape(row.archive_path || '') + '</p>',
    '<p>Record: ' + htmlEscape(row.id) + '</p>',
  ].join('');
  return [{ json: { id: row.id, subject: '[TEST] Document review retry: ' + filename, message_html: messageHtml }, pairedItem: { item: index } }];
});

